-- Catalog expansion 2026-09-24: realistic Egyptian & global items across thin
-- categories (sandwiches, fast food, pizza, pasta, sushi, tagens, vegetables,
-- fruits, dairy, drinks). Per-serving values. Idempotent: skips existing names.
) AS v(name, name_ar, category, calories, protein_g, carbs_g, fat_g, fiber_g, sugars_g, sodium_mg, serving_size, serving_unit) WHERE NOT EXISTS (SELECT 1 FROM foods f WHERE lower(f.name) = lower(v.name)) RETURNING id, name;